#!/usr/bin/env php
<?php
declare(strict_types=1);require_once __DIR__.'/../includes/task_system_operations.php';$o=getopt('',['dry-run','apply','verify:','output-dir::']);
try{if(isset($o['verify'])){$r=TaskSystemOperations::verifyBackup((string)$o['verify']);echo json_encode($r,JSON_PRETTY_PRINT).PHP_EOL;exit($r['valid']?0:2);}if(!isset($o['dry-run'])&&!isset($o['apply']))throw new InvalidArgumentException('Choose --dry-run, --apply, or --verify=<directory>.');$files=TaskSystemOperations::backupFiles();if(isset($o['dry-run'])){echo json_encode(['mode'=>'dry-run','files'=>array_map([TaskSystemOperations::class,'relative'],$files),'database_strategy'=>'SQLite VACUUM INTO','mutations'=>0],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL;exit;}
$base=(string)($o['output-dir']??TaskSystemOperations::root().'/storage/task-system-backups');$dir=$base.'/'.gmdate('Ymd_His').'_'.bin2hex(random_bytes(4));if(!mkdir($dir,0700,true))throw new RuntimeException('Unable to create backup directory.');$items=[];
foreach($files as $source){$isDb=$source===TaskSystemOperations::databasePath();$rel=$isDb?'database/app.sqlite':'files/'.TaskSystemOperations::relative($source);$dest=$dir.'/'.$rel;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0700,true);if($isDb){$db=TaskSystemOperations::open($source,false);$db->exec('VACUUM INTO '.$db->quote($dest));}else{if(!copy($source,$dest))throw new RuntimeException('Backup copy failed.');}chmod($dest,0600);$items[]=['path'=>$rel,'bytes'=>filesize($dest),'sha256'=>hash_file('sha256',$dest)];}
$manifest=['format'=>1,'created_at'=>gmdate('c'),'files'=>$items];file_put_contents($dir.'/manifest.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);chmod($dir.'/manifest.json',0600);$result=TaskSystemOperations::verifyBackup($dir);echo json_encode(['mode'=>'apply','backup'=>basename($dir)]+$result,JSON_PRETTY_PRINT).PHP_EOL;exit($result['valid']?0:2);}catch(Throwable $e){fwrite(STDERR,'Backup failed: '.$e->getMessage().PHP_EOL);exit(2);}
